using Godot;
using System;
using System.Linq;
using System.Threading.Tasks;
public partial class MigrationScene {
 const double WoodlandZ=-690;double WoodlandX=>game.World.RouteX(WoodlandZ)-65;
 const string WoodlandJournal="woodland-camp/journal";
 string WoodlandEnemy(int i)=>$"story/woodland/{game.Save.Seed}/{i}";
 bool woodlandFixture;Node3D woodlandRoot;
 static readonly Vector2[] WoodlandSpikes={new(-5,6),new(5,4),new(1,-7)};
 bool InWoodlandCamp(double x,double z)=>ExpeditionGame.Distance(x,z,WoodlandX,WoodlandZ)<12;
 Vector3 WoodlandPoint(float x,float z)=>Ground(WoodlandX+x,WoodlandZ+z);
 bool WoodlandSpent(int i)=>game.World.Changes.SpentTraps.Contains($"woodland/spikes/{i}");
 void SpawnWoodlandCamp(){if(dungeon!=null||!NearActiveSurface(WoodlandPoint(0,0),200))return;
  if(!uniqueObjects.Contains("story/woodland-camp")){woodlandRoot=new Node3D{Name="TheFirstFish",Position=WoodlandPoint(0,0)};worldRoot.AddChild(woodlandRoot);props.Add(new(){Id="story/woodland-camp",Kind=20,Node=woodlandRoot,Position=woodlandRoot.Position});uniqueObjects.Add("story/woodland-camp");
   WoodlandTent(-3,-3,true);WoodlandTent(5,-2,false);
   var fire=WoodlandObject("ColdHearth",0,2);for(int i=0;i<12;i++){float a=i*Mathf.Tau/12;Ellipsoid(fire,new(Mathf.Sin(a)*.75f,.12f,Mathf.Cos(a)*.75f),new(.22f,.17f,.18f),new(.30f,.31f,.28f));}for(int i=0;i<4;i++){var log=Box(fire,new(0,.12f,i*.12f-.2f),new(1,.15f,.15f),Wood);log.RotationDegrees=new(0,i*47,0);}Tube(fire,new(-1,0,0),new(0,1.5f,0),.035f,Wood);Tube(fire,new(1,0,0),new(0,1.5f,0),.035f,Wood);Tube(fire,new(0,1.5f,0),new(0,1.5f,.7f),.025f,Wood);var pot=Ellipsoid(fire,new(.9f,.22f,.65f),new(.35f,.24f,.35f),Steel);pot.RotationDegrees=new(65,0,0);Ellipsoid(fire,new(1.3f,.025f,.8f),new(.55f,.02f,.3f),new(.22f,.19f,.12f));
   var bag=WoodlandObject("JournalBackpack",-1,-3);Bevel(bag,new(0,.25f,0),new(.45f,.5f,.3f),new(.37f,.32f,.19f));StoryPaper(bag,new(0,.52f,0));Tube(bag,new(-.15f,.1f,.2f),new(-.15f,.45f,.2f),.025f,Wood);
   var child=WoodlandObject("QuietBlanket",-3,-3);Ellipsoid(child,new(0,.16f,0),new(.38f,.18f,.72f),new(.38f,.40f,.32f));Box(child,new(.5f,.07f,.4f),new(.15f,.12f,.24f),new(.38f,.28f,.17f));Box(child,new(.7f,.07f,.4f),new(.15f,.12f,.24f),new(.38f,.28f,.17f));Tube(child,new(-.5f,.05f,-.7f),new(-.1f,.05f,-1.3f),.018f,Wood);
   var supplies=WoodlandObject("Lessons",4,2);Box(supplies,new(0,.18f,0),new(.8f,.36f,.5f),Wood,true);Tube(supplies,new(-.5f,.4f,0),new(-1.5f,.6f,-1),.025f,Wood);Tube(supplies,new(-1.5f,.6f,-1),new(-1.5f,.05f,-1),.004f,Steel);Box(supplies,new(.6f,.1f,.2f),new(.5f,.2f,.18f),Cloth);
   for(int i=0;i<3;i++){var trap=WoodlandObject("Spikes"+i,WoodlandSpikes[i].X,WoodlandSpikes[i].Y);for(int s=0;s<5;s++)Tube(trap,new((s-2)*.25f,0,0),new((s-2)*.25f,.65f,-.35f),.055f,Wood,0);Box(trap,new(0,.1f,0),new(1.5f,.12f,.2f),Wood);}for(int i=0;i<6;i++){var fence=WoodlandObject("BrokenDefense",-7+i*2.5f,-6);Tube(fence,Vector3.Zero,new(.3f,1,-.2f),.07f,Wood,0);}
  }
  if(CoopClient||((testing||coopCheckRole!=null)&&!woodlandFixture))return;for(int i=0;i<3;i++){var p=WoodlandPoint(i==0?-3:i==1?-10:10,i==0?-1:i==1?4:-4);AddEnemy(WoodlandEnemy(i),p.X,p.Z,2);var e=infected.FirstOrDefault(e=>e.Id==WoodlandEnemy(i));if(i==0&&e!=null&&e.BossState==""){e.BossState="woodland-kneel";AnimateCharacter(e);}}
 }
 Node3D WoodlandObject(string name,float x,float z){var n=new Node3D{Name=name,Position=WoodlandPoint(x,z)-woodlandRoot.Position};woodlandRoot.AddChild(n);return n;}
 void WoodlandTent(float x,float z,bool torn){var n=WoodlandObject(torn?"TornTent":"MentorsTent",x,z);var canvas=new Color(.36f,.39f,.28f);for(int side=-1;side<=1;side+=2){var roof=Box(n,new(side*.65f,.75f,0),new(.08f,2,2.7f),canvas);roof.RotationDegrees=new(0,0,side*40);Tube(n,new(side*1.35f,0,1.5f),new(0,1.55f,1.2f),.018f,Steel);Tube(n,new(side*1.35f,0,-1.5f),new(0,1.55f,-1.2f),.018f,Steel);}Box(n,new(0,.02f,0),new(2.6f,.04f,2.7f),Cloth);Box(n,new(0,.7f,-1.35f),new(2,1.4f,.06f),canvas,true);if(torn){for(int i=0;i<3;i++){var flap=Box(n,new(-.8f+i*.22f,.65f,1.38f),new(.18f,1.3f,.03f),canvas);flap.RotationDegrees=new(12,0,-20+i*18);}Box(n,new(.8f,.1f,1.5f),new(.7f,.05f,1),canvas);}else Box(n,new(.7f,.65f,1.35f),new(.6f,1.3f,.04f),canvas);}
 bool TickWoodlandKneeler(Infected e){if(e.BossState!="woodland-kneel")return false;if(Distance(player.Position,e.Body.Position)<6||e.Memory>0||e.Hp<e.MaxHp){e.BossState="woodland-awake";e.Visual.Position=Vector3.Zero;e.Memory=8;e.Target=player.Position;return false;}AnimateCharacter(e);return true;}
 void WoodlandPose(Infected e){if(e.BossState!="woodland-kneel"||!e.Visual.HasNode("Torso"))return;e.Visual.Position=new(0,-.55f,0);e.Visual.GetNode<Node3D>("Torso").RotationDegrees=new(35,0,0);foreach(string side in new[]{"Left","Right"}){e.Visual.GetNode<Node3D>(side+"Leg").RotationDegrees=new(-70,0,0);e.Visual.GetNode<Node3D>(side+"Leg/Knee").RotationDegrees=new(110,0,0);e.Visual.GetNode<Node3D>(side+"Arm").RotationDegrees=new(-45,0,0);}}
 string WoodlandOperation(){if(dungeon!=null||!GodotObject.IsInstanceValid(woodlandRoot)||!woodlandRoot.IsInsideTree())return "";for(int i=0;i<3;i++)if(!WoodlandSpent(i)&&Distance(player.Position,WoodlandPoint(WoodlandSpikes[i].X,WoodlandSpikes[i].Y))<2)return "trap/"+i;return Distance(player.Position,WoodlandPoint(-1,-3))<2.3?"journal":"";}
 string WoodlandPrompt()=>WoodlandOperation() switch{"journal"=>"F / SEARCH WEATHERED BACKPACK",var s when s.StartsWith("trap/")=>"F / DISARM MAKESHIFT SPIKES",_=>""};
 bool WoodlandInteract(){string op=WoodlandOperation();if(op=="")return false;if(!CoopRequest("woodland",op))WoodlandAction(op);return true;}
 void WoodlandAction(string op){if(CoopClient||op!=WoodlandOperation())return;if(op.StartsWith("trap/")){int i=int.Parse(op.Substring(5));game.Change(()=>game.World.Changes.SpentTraps.Add($"woodland/spikes/{i}"));game.Notice="Spikes lowered safely";}else{if(!game.Skills.Defeated.Contains(WoodlandEnemy(0))){game.Notice="An infected is still beside the tent";return;}game.Change(()=>{if(!game.Profile.Journal.Seen.Contains(WoodlandJournal))game.Profile.Journal.Seen.Add(WoodlandJournal);});if(CoopHost&&coopActor>0)RpcId(coopActor,nameof(CoopWoodlandJournal));else ShowWoodlandJournal();}if(CoopHost&&coopActors.Count>0)Rpc(nameof(CoopWorldUpdate),Json.Write(WorldSnapshot()));}
 void TickWoodlandTraps(){if(CoopClient||dungeon!=null)return;foreach(var pair in MillPlayers())for(int i=0;i<3;i++){var p=WoodlandPoint(WoodlandSpikes[i].X,WoodlandSpikes[i].Y);if(WoodlandSpent(i)||Distance(pair.Body.Position,p)>.65f||Math.Abs(pair.Body.Position.Y-p.Y)>1.5)continue;game.Change(()=>game.World.Changes.SpentTraps.Add($"woodland/spikes/{i}"));MillDamage(pair.Game,pair.Body,8,false);foreach(var e in infected)if(Distance(e.Body.Position,p)<32){e.Memory=8;e.Target=p;}EnemySound(p,1);pair.Game.Notice="Makeshift spikes / the noise carries through the trees";if(CoopHost&&coopActors.Count>0)Rpc(nameof(CoopWorldUpdate),Json.Write(WorldSnapshot()));}}
 void DrawWoodlandCamp(){if(!GodotObject.IsInstanceValid(woodlandRoot))return;for(int i=0;i<3;i++)if(woodlandRoot.HasNode("Spikes"+i))woodlandRoot.GetNode<Node3D>("Spikes"+i).Scale=new(1,WoodlandSpent(i)?.15f:1,1);}
 const string WoodlandText="DAY 1\nI was closing the shop when he ran into me. No coat. Couldn't get his name out. I took his hand and we kept moving until the city was behind us. His name is Eli. He asked if I knew the way home. I told him we'd find somewhere safe first.\n\nDAY 9\nHis first fish was no bigger than my thumb. You'd think he'd landed a whale. We cooked it together. He insisted I have half. Tomorrow: snares. He has started calling this place our camp.\n\nDAY 23\nHe laid the rabbit trap himself. Checked the wind, covered our tracks, remembered everything. I haven't heard him laugh like that since we left. There are worse things than being needed.\n\nDAY 31\nThe bank gave way. My foot won't take my weight. I told him to follow the creek south. He brought my pack inside instead. 'You didn't leave me,' he said. He spent all afternoon sharpening stakes.\n\nDAY 38\nThey get through sometimes. We mend the fence in daylight. He sleeps with his boots on. One cartridge left. I stared at it today and thought things I cannot bear to write. A boy should never have to keep a grown man alive.\n\nLAST PAGE\nI used the last round at the fence. For a moment he was safe. I have to believe that was the right thing.\nIf someone finds this: his name was Eli. He caught his first fish here. He gave away half of it. That is what you should know about him.\nI can hear them coming again. I'm sorry I couldn't take him home.\n\nThe remaining pages are blank.";
 void ShowWoodlandJournal(){var b=Panel("THE FIRST FISH / A WEATHERED JOURNAL");var scroll=new ScrollContainer{CustomMinimumSize=new(880,450)};b.AddChild(scroll);var pages=new VBoxContainer();scroll.AddChild(pages);Text(pages,WoodlandText);Button(b,"BACK",CloseMenu);}
 [Rpc(MultiplayerApi.RpcMode.Authority,TransferMode=MultiplayerPeer.TransferModeEnum.Reliable)]void CoopWoodlandJournal(){if(CoopClient)ShowWoodlandJournal();}
 async Task WoodlandChecks(){ClearEnemies();woodlandFixture=true;Teleport(WoodlandX,WoodlandZ+12);SpawnWoodlandCamp();MigrationChecks.Assert(infected.Count(e=>e.Id.StartsWith("story/woodland/"))==3,"Woodland camp authored infected");var kneeler=infected.Single(e=>e.Id==WoodlandEnemy(0));MigrationChecks.Assert(TickWoodlandKneeler(kneeler),"Distant infected kneels quietly");player.Position=WoodlandPoint(-1,-3);WoodlandAction("journal");MigrationChecks.Assert(!game.Profile.Journal.Seen.Contains(WoodlandJournal),"Journal guarded");MigrationChecks.Assert(!TickWoodlandKneeler(kneeler),"Close approach wakes infected");KillEnemy(kneeler);WoodlandAction("journal");MigrationChecks.Assert(game.Profile.Journal.Seen.Contains(WoodlandJournal),"Camp journal recovered");CloseMenu();player.Position=WoodlandPoint(-5,6);TickWoodlandTraps();MigrationChecks.Assert(WoodlandSpent(0),"Spikes trigger once");player.Position=WoodlandPoint(5,4);WoodlandAction("trap/1");MigrationChecks.Assert(WoodlandSpent(1),"Spikes disarm safely");game.Persist();var loaded=new ExpeditionGame(game.PathName);MigrationChecks.Assert(loaded.Profile.Journal.Seen.Contains(WoodlandJournal)&&loaded.World.Changes.SpentTraps.Contains("woodland/spikes/0"),"Camp story persists");woodlandFixture=false;ClearEnemies();Teleport(0,12);await ToSignal(GetTree(),SceneTree.SignalName.ProcessFrame);GD.Print("PASS / woodland camp, kneeler, guarded journal, spike trigger/disarm and persistence");}
 async void CaptureWoodland(){try{woodlandFixture=true;ClearEnemies();game.World.Changes.Time=1000;Teleport(WoodlandX,WoodlandZ+12);SpawnWoodlandCamp();paused=true;weaponRoot.Visible=false;camera.GlobalPosition=WoodlandPoint(-10,13)+Vector3.Up*4;camera.LookAt(WoodlandPoint(0,0)+Vector3.Up);await ArtShot("woodland-camp-01-clearing");camera.GlobalPosition=WoodlandPoint(-.5f,2)+Vector3.Up*1.6f;camera.LookAt(WoodlandPoint(-3,-2)+Vector3.Up*.6f);await ArtShot("woodland-camp-02-tent");ShowWoodlandJournal();await ArtShot("woodland-camp-03-journal");GetTree().Quit();}catch(Exception ex){GD.PushError(ex.ToString());GetTree().Quit(1);}}
}
